/* Engineer OS: separate, versioned browser-local data from Prepdesk's IndexedDB. */
(() => {
  "use strict";
  const KEY="engineer-os-v1", VERSION=1;
  const $=s=>document.querySelector(s), esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
  const defaults={start:"2026-12-03",timezone:"Asia/Kolkata",weeklyTarget:80,onboarding:"full",durations:{dsa:25,vocab:10,deep:45,design:45,blog:30,paper:45,lab:150,outage:45,review:15},targets:{dsa:115,blog:45,vocab:200,lab:22,paper:11,outage:22,design:40}};
  const activity={dsa:"DSA and analytical problem-solving",vocab:"Technical vocabulary",deep:"Infrastructure deep dive",design:"System design",blog:"Engineering blog",paper:"Research paper",lab:"Build, Break and Rebuild lab",outage:"Outage postmortem",review:"Weekly review"};
  const objective={dsa:"Attempt one problem independently. Record whether you solved it without help.",vocab:"Learn two technical terms and revise due flashcards.",deep:"Study one roadmap concept, perform a practical exercise, and record the next question.",design:"Study one system and record its requirements, architecture, and trade-offs.",blog:"Read one real engineering article and record the problem, solution, and lessons.",paper:"Advance one reading pass and record the architecture or main contribution.",lab:"Build, break, investigate, rebuild, and document a local experiment.",outage:"Read a sourced incident report and separate documented facts from your interpretation.",review:"Review actual weekly data and choose Monday's first action."};
  const days=[["dsa","vocab","deep","design"],["dsa","vocab","deep","blog"],["dsa","vocab","deep","design"],["dsa","vocab","deep","paper"],["dsa","vocab","deep","blog"],["lab"],["outage","review"]];
  const roadmap=[
    {name:"Networking foundations",topics:"OSI and TCP/IP models|TCP and UDP|DNS|HTTP and HTTPS|TLS|IP addressing|Subnetting|Routing|NAT|Sockets|Ports|Packet analysis",tools:"Wireshark, curl, nslookup, tracert"},
    {name:"Advanced and cloud networking",topics:"Reverse proxies|Load balancing|HTTP/2 and HTTP/3|gRPC|CDNs|AWS VPC|Public and private subnets|Ingress and egress|Service discovery|Docker networking",tools:"NGINX, YARP, Docker, AWS"},
    {name:"Database internals",topics:"B-trees|Indexes|Query execution plans|Transactions|Isolation levels|Locks and deadlocks|Replication|Sharding|Caching",tools:"PostgreSQL, SQL Server, Redis"},
    {name:"Distributed systems",topics:"Consensus|Messaging|Eventual consistency|Idempotency|Retries|Exponential backoff|Circuit breakers|Backpressure|Distributed coordination",tools:"RabbitMQ, Kafka fundamentals, gRPC"},
    {name:"Infrastructure and observability",topics:"Containers|Kubernetes|Scheduling|Orchestration|Metrics|Logs|Distributed traces|SRE|Monitoring and alerting",tools:"Docker, Kubernetes, Prometheus, Grafana, OpenTelemetry"},
    {name:"AI and GPU infrastructure",topics:"GPU architecture fundamentals|Model inference|Inference serving|Batching|Quantization|KV caching|Model serving bottlenecks|Agent reliability|AI system observability",tools:"PyTorch, NVIDIA tooling, model serving frameworks"}
  ];
  const designSeeds="URL shortener|Rate limiter|Notification system|Distributed cache|Real-time flight tracking system|Chat application|Metrics collection system|Distributed logging system|API gateway|Message processing pipeline".split("|");
  const labSeeds="Build a basic round-robin load balancer and investigate what happens when a backend instance stops|Build a TCP client and server and investigate unexpected client disconnections|Build a minimal HTTP server and investigate invalid requests locally|Build a small DNS caching demonstration and investigate stale records|Build an in-memory TTL cache and investigate concurrency|Build a basic rate limiter and test bursts of local traffic|Build a producer-consumer queue using C# Channels and investigate backpressure|Build a RabbitMQ producer and consumer and investigate duplicate deliveries|Perform a database indexing experiment and compare query performance|Build a concurrent database transaction experiment and investigate deadlocks|Build a circuit breaker and simulate a downstream service failure|Build a distributed tracing demonstration and identify a deliberately slow service".split("|");
  const paperSeeds="End-to-End Arguments in System Design|Jupiter Rising|Congestion Avoidance and Control|Large-scale Cluster Management at Google with Borg|Dynamo: Amazon's Highly Available Key-value Store|Bigtable|In Search of an Understandable Consensus Algorithm (Raft)|MapReduce|Dapper|Spanner|Attention Is All You Need|Efficient Memory Management for Large Language Model Serving with PagedAttention".split("|");
  const outageSeeds="Meta global outage, October 2021|AWS DynamoDB outage, October 2025|GitHub database outage, October 2018|Cloudflare global outage, November 2025|Cloudflare network congestion incident, August 2025".split("|");
  const directories={blog:[["Netflix TechBlog","https://netflixtechblog.com/"],["Cloudflare Blog","https://blog.cloudflare.com/"],["Uber Engineering","https://www.uber.com/blog/engineering/"],["Meta Engineering","https://engineering.fb.com/"],["Discord Engineering","https://discord.com/category/engineering"],["AWS Builders' Library","https://aws.amazon.com/builders-library/"],["AWS Architecture Blog","https://aws.amazon.com/blogs/architecture/"],["Google Cloud Blog","https://cloud.google.com/blog/"],["Stripe Engineering","https://stripe.com/blog/engineering/"],["Google SRE Books","https://sre.google/books/"],["Engineering.fyi","https://www.engineering.fyi/"]],outage:[["Postmortem collection","https://github.com/danluu/post-mortems"],["AWS incident reports","https://aws.amazon.com/premiumsupport/technology/pes/"],["Cloudflare outage reports","https://blog.cloudflare.com/tag/outage/"]]};
  const vocabRaw=`Networking|North-south traffic|Traffic entering or leaving a service boundary|A public API request entering a private network
Networking|East-west traffic|Traffic between services inside a network|A checkout service calls inventory
Networking|Ingress|Incoming network traffic|An ingress controller receives an HTTP request
Networking|Egress|Outgoing network traffic|A service calls a payment provider
Networking|Round-trip time|Time for a request and response to travel|Ping measures network round-trip time
Networking|Multiplexing|Sharing one connection among multiple streams|HTTP/2 carries several requests on one connection
Networking|Head-of-line blocking|One delayed item holds up following items|A slow packet stalls ordered delivery
Networking|Network partition|Nodes cannot communicate although they still run|A broken link separates two database replicas
Architecture|Tight coupling|A change in one component forces changes in another|Two services depend on each other's internal tables
Architecture|Loose coupling|Components interact through stable interfaces|An event producer does not know its consumers
Architecture|Cohesion|How closely related a component's responsibilities are|An authentication module handles identity only
Architecture|Fan-out|One request produces many downstream operations|A feed request queries several services
Architecture|Service boundaries|The interfaces and responsibilities separating services|Billing owns invoices and exposes an API
Architecture|Separation of concerns|Keep different responsibilities in distinct parts|Validation and persistence live in different layers
Reliability|Blast radius|The scope affected by a failure|One region failing leaves other regions available
Reliability|Fault isolation|Prevent one failure from spreading|A separate worker pool protects the API
Reliability|Cascading failure|An initial failure causes further failures|Retries overload an already slow database
Reliability|Graceful degradation|Keep a reduced service available during failure|Show cached results when search is unavailable
Reliability|Single point of failure|One component whose failure stops a system|A lone database server takes the site down
Reliability|Fault tolerance|Continue operating despite some failures|A replica takes over after a node fails
Distributed systems|Idempotency|Repeating an operation has the same effect as doing it once|A payment request ID prevents double charging
Distributed systems|Eventual consistency|Replicas converge after a delay|A new post appears on all feeds shortly later
Distributed systems|Quorum|A minimum number of nodes required to agree|Two of three replicas confirm a write
Distributed systems|Backpressure|Slow producers when consumers cannot keep up|A queue limits incoming jobs
Distributed systems|Split-brain|Separated nodes both believe they are leader|Two primaries accept conflicting writes
Distributed systems|Consensus|Nodes agree on shared state despite failures|Raft elects one leader
Performance|Throughput|Work completed per unit time|A server processes 800 requests per second
Performance|Tail latency|Latency of the slowest requests|The p99 API response takes 900 ms
Performance|Contention|Competition for a shared resource|Threads wait on one lock
Performance|Saturation|A resource reaches its usable capacity|CPU stays near 100 percent
Performance|Bottleneck|The limiting step in a system|Database writes cap request throughput
Performance|Write amplification|One logical write causes multiple physical writes|An index update writes several disk pages
Infrastructure|Control plane|Components that configure and direct a system|Kubernetes API updates desired state
Infrastructure|Data plane|Components that carry actual workload traffic|A proxy forwards live requests
Infrastructure|Orchestration|Automated coordination of components|Kubernetes schedules containers
Infrastructure|Resource contention|Workloads compete for finite capacity|Two containers compete for CPU
Infrastructure|Service discovery|Finding the current address of a service|DNS resolves a service name to healthy pods
Observability|Telemetry|Measurements emitted by a running system|An API exports request counts and traces
Observability|Cardinality|Number of distinct label combinations|User IDs create millions of metric series
Observability|Distributed tracing|Following one request across services|A trace shows API, cache, and database spans
Observability|SLI|A measured service quality indicator|Successful request percentage is an SLI
Observability|SLO|A target for a service quality indicator|99.9 percent availability is an SLO
Observability|Error budget|Allowed unreliability within an SLO|An SLO permits roughly 43 minutes downtime monthly
Deployment|Canary release|Release to a small subset before wider rollout|One percent of traffic reaches new code
Deployment|Rolling deployment|Replace instances gradually|Pods update one batch at a time
Deployment|Blue-green deployment|Switch traffic between two full environments|Traffic moves from blue to green servers
Deployment|Rollback|Restore an earlier version after trouble|Revert a failing release
Databases|Replication lag|Delay before a replica reflects a write|A read replica shows an old balance briefly
Databases|Transaction isolation|Rules for visibility between concurrent transactions|Serializable isolation prevents certain anomalies
Databases|Optimistic locking|Detect conflicts when saving rather than locking first|A version column rejects stale updates
Databases|MVCC|Keep row versions for concurrent readers and writers|PostgreSQL readers see a snapshot
Databases|Sharding|Split data across database partitions|Customers are assigned to separate shards
Databases|Index selectivity|How well an index narrows matching rows|A unique email index is highly selective`;
  const schema={dsa:["date","problemTitle","problemUrl","topic","difficulty","timeSpent","attemptedIndependently","hintRequired","solutionUnderstood","solvedIndependently","revisitRequired","notes"],design:["systemName","status","date","resource","problemStatement","functionalRequirements","nonFunctionalRequirements","architecture","dataFlow","components","scalability","bottlenecks","failureScenarios","decisions","alternatives","tradeoffs","questions","projectApplications","diagramUrl"],blog:["articleTitle","company","articleUrl","category","status","dateAdded","dateCompleted","problem","solution","architecture","terminology","tradeoffs","lessons","application","questions"],paper:["title","authors","year","phase","technology","paperUrl","status","abstractSummary","problem","previousApproaches","architecture","contribution","diagrams","limitations","takeaways","applications","questions","pass"],lab:["experimentTitle","technology","status","hypothesis","initialImplementation","failureScenario","predictedBehavior","observedBehavior","rootCause","improvedImplementation","measurements","githubUrl","documentation","lessons","timeSpent","aiAssistance"],outage:["incidentName","status","company","incidentDate","officialUrl","affectedSystems","timeline","trigger","rootCause","propagation","blastRadius","detection","response","decisionMaking","tradeoffs","mitigation","recovery","correctiveActions","lessons","projectRisks","assumptions"]};
  const seed=()=>({version:VERSION,settings:structuredClone(defaults),days:{},focus:null,records:{dsa:[],design:designSeeds.map(systemName=>({id:uid(),systemName,status:"backlog"})),blog:[],paper:paperSeeds.map((title,i)=>({id:uid(),title,status:"backlog",phase: i<3?1:i<6?3:i<10?4:6,pass:0})),lab:labSeeds.map(experimentTitle=>({id:uid(),experimentTitle,status:"backlog",technology:"C# / .NET"})),outage:outageSeeds.map(incidentName=>({id:uid(),incidentName,status:"backlog"})),vocab:vocabRaw.split("\n").map(line=>{const [category,term,meaning,example]=line.split("|");return{id:uid(),category,term,meaning,definition:meaning,example,useCase:"",tradeoff:"",familiarity:0,revisionStatus:"new",nextRevision:""};})},roadmap:roadmap.map((p,i)=>({id:uid(),name:p.name,order:i+1,tools:p.tools,topics:p.topics.split("|").map(name=>({id:uid(),name,done:false}))})),reviews:{}});
  let data,view="today",selected="",focusUi=false,libraryFilter="",categoryFilter="all",flashIndex=0,showAnswer=false,editing=null,notice="";
  function load(){try{const raw=localStorage.getItem(KEY);if(!raw)return seed();const obj=JSON.parse(raw);if(!valid(obj))throw Error("Invalid saved data");return obj;}catch(e){throw Error(`Engineer OS data could not be read: ${e.message}. Export or inspect browser storage before clearing it.`);}}
  function valid(x){if(!x||x.version!==VERSION||!x.settings||!/^\d{4}-\d{2}-\d{2}$/.test(x.settings.start||"")||!x.settings.durations||!x.settings.targets||!x.days||typeof x.days!=="object"||Array.isArray(x.days)||!x.records||!Array.isArray(x.roadmap)||!x.reviews||typeof x.reviews!=="object")return false;try{new Intl.DateTimeFormat("en",{timeZone:x.settings.timezone});}catch{return false;}return ["dsa","design","blog","paper","lab","outage","vocab"].every(k=>Array.isArray(x.records[k])&&x.records[k].every(r=>r&&typeof r==="object"&&typeof r.id==="string"))&&x.roadmap.every(p=>p&&typeof p.name==="string"&&Array.isArray(p.topics)&&p.topics.every(t=>typeof t.name==="string"))&&Object.entries(x.days).every(([k,d])=>/^\d{4}-\d{2}-\d{2}$/.test(k)&&d&&typeof d.tasks==="object"&&Array.isArray(d.rescheduled));}
  function save(){localStorage.setItem(KEY,JSON.stringify(data));}
  function dateKey(date=new Date()){return new Intl.DateTimeFormat("en-CA",{timeZone:data.settings.timezone,year:"numeric",month:"2-digit",day:"2-digit"}).format(date);}
  const addDays=(key,n)=>{const d=new Date(`${key}T12:00:00Z`);d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
  const diff=(a,b)=>Math.round((Date.parse(`${a}T12:00:00Z`)-Date.parse(`${b}T12:00:00Z`))/86400000);
  const weekday=key=>(new Date(`${key}T12:00:00Z`).getUTCDay()+6)%7;
  const weekStart=key=>addDays(key,-weekday(key));
  const end=()=>addDays(data.settings.start,179);
  function schedule(key){if(diff(key,data.settings.start)<0||diff(key,end())>0)return[];const w=weekday(key),week=Math.floor(diff(key,data.settings.start)/7)+1;let ids=[...days[w]];if(data.settings.onboarding==="gradual"){if(week===1)ids=ids.filter(x=>["dsa","vocab","deep"].includes(x));if(week===2)ids=ids.filter(x=>!["design","outage","paper","review"].includes(x));if(week===3)ids=ids.filter(x=>x!=="paper");}return ids.map(id=>({id,title:activity[id],minutes:data.settings.durations[id]||25,required:true}));}
  function day(key){return data.days[key]||(data.days[key]={tasks:{},mode:"normal",notes:"",order:[],rescheduled:[]});}
  function tasks(key){const base=schedule(key),weekend=base.length&&weekday(key)>=5?[{id:"optional-dsa",title:"Optional DSA revision",minutes:5,required:false},{id:"optional-vocab",title:"Optional vocabulary revision",minutes:5,required:false},{id:"optional-deep",title:"Optional infrastructure revision",minutes:10,required:false}]:[];const mvd=data.days[key]?.mode==="mvd"?[{id:"mvd-dsa",title:"Minimum viable DSA",minutes:5,required:false},{id:"mvd-deep",title:"Minimum viable infrastructure learning",minutes:10,required:false},{id:"mvd-vocab",title:"Minimum viable vocabulary revision",minutes:5,required:false}]:[];const extra=(data.days[key]?.rescheduled||[]).map(x=>({...x,required:false}));const order=data.days[key]?.order||[];return [...mvd,...base,...weekend,...extra].sort((a,b)=>(order.indexOf(a.id)<0?99:order.indexOf(a.id))-(order.indexOf(b.id)<0?99:order.indexOf(b.id)));}
  function mvdComplete(key){return data.days[key]?.mode==="mvd"&&["mvd-dsa","mvd-deep","mvd-vocab"].every(id=>completed(rec(key,id)));}
  function rec(key,id){return data.days[key]?.tasks?.[id]||{status:"pending",minutes:0,note:"",next:""};}
  const completed=r=>r.status==="completed";
  function stats(key){const t=tasks(key).filter(x=>x.required),r=t.map(x=>rec(key,x.id)),done=r.filter(completed).length;return{total:t.length,done,partial:r.filter(x=>x.status==="partial").length,missed:r.filter(x=>x.status==="skipped"||x.status==="pending").length,percent:t.length?Math.round(done/t.length*100):0,focused:Object.values(data.days[key]?.tasks||{}).reduce((n,x)=>n+(Number(x.minutes)||0),0),planned:t.reduce((n,x)=>n+x.minutes,0)};}
  function challenge(){const today=dateKey(),elapsed=Math.max(0,Math.min(180,diff(today,data.settings.start)+1));return{today,elapsed,remaining:180-elapsed,day:elapsed?elapsed:0,pct:Math.round(elapsed/180*100)};}
  function phase(key){const n=diff(key,data.settings.start);return data.roadmap[Math.max(0,Math.min(5,Math.floor(n/30)))]||data.roadmap[0];}
  function streaks(){const today=dateKey();let current=0,longest=0,run=0;for(let i=0;i<180;i++){const k=addDays(data.settings.start,i);if(k>today)break;const s=stats(k),ok=s.total>0&&s.done===s.total;if(ok){run++;longest=Math.max(longest,run);}else run=0;if(k===today||k===addDays(today,-1))current=Math.max(current,run);}return{current,longest};}
  function heading(title,sub="",actions=""){return `<div class="lead"><div><div class="eyebrow">Engineer OS / The 180-Day Engineering Challenge</div><h1>${esc(title)}</h1><div class="sub">${sub}</div></div><div class="row">${actions}</div></div>`;}
  function btn(action,label,kind="secondary",extra=""){return `<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;}
  function safeLink(value){try{const u=new URL(value);return /^https?:$/.test(u.protocol)?u.href:"";}catch{return"";}}
  function link(value,label="Open source"){const url=safeLink(value);return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:"";}
  function renderToday(){const c=challenge(),key=selected||c.today,s=stats(key),ts=tasks(key),d=day(key),active=phase(key),pending=ts.filter(x=>!completed(rec(key,x.id)));const outside=!schedule(key).length;
    return `${heading(key===c.today?"Today":key,`${new Date(`${key}T12:00:00Z`).toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric",year:"numeric",timeZone:"UTC"})} · ${c.day?`Challenge day ${Math.max(1,diff(key,data.settings.start)+1)} of 180`:"Challenge begins soon"}`,`${btn("start","Start My Day","",outside?"disabled":"")}${btn("mvd",d.mode==="mvd"?"Return to normal day":"Minimum Viable Day","quiet",outside?"disabled":"")}`)}
      ${notice?`<p class="notice">${esc(notice)}</p>`:""}
      <div class="grid four"><div class="card metric"><b>${c.day}/180</b><span>Current challenge day · ${Math.max(0,c.day-1)} days completed</span></div><div class="card metric"><b>${c.remaining}</b><span>Days remaining</span></div><div class="card metric"><b>${c.pct}%</b><span>Challenge elapsed</span></div><div class="card metric"><b>${s.done}/${s.total}</b><span>Required activities complete</span></div></div>
      <div class="grid two" style="margin-top:15px"><section class="card"><div class="eyebrow">Your execution plan</div><h2>${esc(active.name)}</h2><p class="sub">${outside?"No required activities outside the challenge dates.":`${s.planned} planned minutes · ${s.focused} focused minutes · ${pending.length} activities remaining`}</p><div class="progress"><span style="width:${s.percent}%"></span></div>${ts.map(x=>{const r=rec(key,x.id);return `<div class="task"><div><label><input type="checkbox" data-complete="${esc(x.id)}" data-date="${key}" ${completed(r)?"checked":""}> <strong style="display:inline">${esc(x.title)}</strong></label><small>${x.minutes} min · ${x.required?"Required":x.id.startsWith("mvd-")?"Minimum viable":"Optional / rescheduled"}${r.next?` · Next: ${esc(r.next)}`:""}</small></div><select aria-label="Status for ${esc(x.title)}" data-status="${esc(x.id)}" data-date="${key}">${["pending","in-progress","completed","partial","skipped"].map(st=>`<option value="${st}" ${r.status===st?"selected":""}>${st.replace("-"," ")}</option>`).join("")}</select><div class="row"><button class="btn small quiet" data-action="move-up" data-id="${esc(x.id)}" data-date="${key}" aria-label="Move ${esc(x.title)} earlier">Move earlier</button><button class="btn small secondary" data-action="task-note" data-id="${esc(x.id)}" data-date="${key}">Note / evidence</button><button class="btn small quiet" data-action="reschedule" data-id="${esc(x.id)}" data-date="${key}">Reschedule</button></div></div>`;}).join("")||`<p class="sub">Your first scheduled day is ${data.settings.start}.</p>`}
      </section><aside class="grid"><section class="card"><div class="eyebrow">Commitments</div><h2>Start with the next action</h2>${pending.map(x=>rec(key,x.id).next?`<p><b>${esc(x.title)}:</b> ${esc(rec(key,x.id).next)}</p>`:"").join("")||`<p class="sub">No pending next actions. Begin the first activity and keep planning short.</p>`}<p class="sub">${d.mode==="mvd"?"Minimum viable day: 5 minutes DSA, 10 minutes infrastructure, 5 minutes vocabulary revision. Standard completion still uses the normal schedule.":"A missed day stays in your history. Start again with today's first activity."}</p></section><section class="card"><h2>At a glance</h2><p>${s.percent}% daily completion · ${s.focused}/${s.planned} focused/planned minutes</p><p>${streaks().current} current streak · ${streaks().longest} longest streak</p><p>${Object.values(data.days).flatMap(x=>Object.values(x.tasks||{})).filter(completed).length} completed activities overall</p><p class="sub">Progress is saved in this browser only. Export a backup from Settings regularly.</p></section></aside></div>`;
  }
  function renderFocus(){const f=data.focus,key=f?.date||dateKey(),ts=tasks(key),t=ts.find(x=>x.id===f?.id);if(!f||!t){data.focus=null;save();view="today";return renderToday();}const r=rec(key,t.id),remaining=Math.max(0,Math.ceil((f.remainingMs-(f.running?Date.now()-f.startedAt:0))/1000));return `<div class="focus">${heading("Focus session",`${key} · ${esc(t.title)}`,`${btn("close-focus","Leave focus","quiet")}`)}<section class="card"><div class="eyebrow">Current objective</div><h2>${esc(t.title)}</h2><p class="sub">${esc(r.next||objective[t.id]||`Work independently for ${t.minutes} minutes. Record what you actually learned.`)}</p>${f.breakUntil&&f.breakUntil>Date.now()?`<p class="notice">Break in progress until ${new Date(f.breakUntil).toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"})}. Resume when ready.</p>`:""}<div class="timer" id="focus-clock">${Math.floor(remaining/60).toString().padStart(2,"0")}:${(remaining%60).toString().padStart(2,"0")}</div><div class="row">${btn(f.running?"pause":"resume",f.running?"Pause":"Resume","secondary")}${btn("break","Five-minute break","quiet")}${btn("finish-focus","Finish timebox","quiet")}</div><div class="field" style="margin-top:24px"><label for="focus-note">Short learning note</label><textarea id="focus-note" placeholder="What did you understand or try?">${esc(f.note||"")}</textarea></div><div class="field"><label for="focus-next">What is the exact next action you need to take?</label><input id="focus-next" value="${esc(f.next||"")}" placeholder="One concrete step"></div><div class="row">${btn("complete-focus","Mark activity complete","")}${btn("partial-focus","Partially complete","secondary")}${btn("continue-focus","Continue to next activity","quiet")}</div><p class="sub">The timer ending does not mark an activity complete. Choose its status explicitly.</p></section></div>`;}
  function renderWeek(){const key=selected||dateKey(),start=weekStart(key),rows=Array.from({length:7},(_,i)=>{const k=addDays(start,i),s=stats(k);return `<div class="item"><strong>${k} · ${["Mon","Tue","Wed","Thu","Fri","Sat","Sun"][i]} <span class="badge ${s.percent===100&&s.total?"done":""}">${s.done}/${s.total}</span></strong><small>${tasks(k).map(x=>x.title).join(" · ")||"Outside challenge"}</small><button class="btn small quiet" data-action="inspect" data-date="${k}">Open day</button></div>`;}).join("");const totals=weekStats(start);return `${heading("Weekly plan",`Monday ${start} through Sunday ${addDays(start,6)}`,`${btn("previous-week","Previous","quiet")}${btn("next-week","Next","quiet")}`)}<div class="grid two"><section class="card"><h2>Automatically scheduled</h2>${rows}</section><aside class="card"><h2>Required activity consistency</h2><div class="metric"><b>${totals.percent}%</b><span>${totals.done} of ${totals.total} required activities completed · target ${data.settings.weeklyTarget}%</span></div><div class="progress"><span style="width:${totals.percent}%"></span></div><p class="sub">Optional weekend revision and rescheduled tasks do not change consistency. The week resets every Monday, while prior records remain.</p><h3>Weekly targets</h3>${[["DSA",5],["Vocabulary sessions",5],["New terms",10],["Deep dives",5],["System designs",2],["Blogs",2],["Papers",1],["Labs",1],["Outages",1],["Reviews",1]].map(([name,n])=>`<p>${name}: ${n}</p>`).join("")}</aside></div>`;}
  function weekStats(start){let total=0,done=0,partial=0,focused=0;for(let i=0;i<7;i++){const s=stats(addDays(start,i));total+=s.total;done+=s.done;partial+=s.partial;focused+=s.focused;}return{total,done,partial,focused,percent:total?Math.round(done/total*100):0};}
  function spanStats(start,length){let total=0,done=0;for(let i=0;i<length;i++){const s=stats(addDays(start,i));total+=s.total;done+=s.done;}return{total,done,percent:total?Math.round(done/total*100):0};}
  function libraryTitle(type){return{dsa:"DSA log",design:"System design journal",blog:"Engineering blog library",paper:"Research papers",lab:"Engineering laboratory",outage:"Outage archive"}[type];}
  function label(key){return key.replace(/([A-Z])/g," $1").replace(/^./,x=>x.toUpperCase());}
  function fieldInput(key,value=""){const area=/notes|summary|problem|requirements|architecture|flow|components|scalability|bottlenecks|scenarios|decisions|alternatives|tradeoffs|questions|applications|hypothesis|implementation|behavior|cause|measurements|lessons|timeline|propagation|response|mitigation|recovery|actions|risks|meaning|definition|example|useCase/i.test(key);const required=["problemTitle","systemName","articleTitle","title","experimentTitle","incidentName","term"].includes(key)?"required":"";const type=/date/i.test(key)?"date":/url|link/i.test(key)?"url":/year|phase|timeSpent/i.test(key)?"number":"text";if(["attemptedIndependently","hintRequired","solutionUnderstood","solvedIndependently","revisitRequired"].includes(key))return `<div class="field"><label><input type="checkbox" name="${key}" ${value?"checked":""}> ${label(key)}</label></div>`;if(key==="status")return `<div class="field"><label for="f-${key}">${label(key)}</label><select id="f-${key}" name="${key}">${["backlog","reading","in-progress","completed","paused"].map(v=>`<option ${value===v?"selected":""}>${v}</option>`).join("")}</select></div>`;if(key==="pass")return `<div class="field"><label for="f-pass">Reading pass</label><select id="f-pass" name="pass">${[0,1,2,3].map(v=>`<option value="${v}" ${Number(value)===v?"selected":""}>${v?`Pass ${v}`:"Not started"}</option>`).join("")}</select></div>`;return `<div class="field"><label for="f-${key}">${label(key)}</label>${area?`<textarea id="f-${key}" name="${key}" ${required}>${esc(value)}</textarea>`:`<input id="f-${key}" name="${key}" type="${type}" value="${esc(value)}" ${required}>`}</div>`;}
  function renderLibrary(type){const list=data.records[type],query=libraryFilter.toLowerCase(),filtered=list.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(query))),primary={dsa:"problemTitle",design:"systemName",blog:"articleTitle",paper:"title",lab:"experimentTitle",outage:"incidentName"}[type];const dir=directories[type]||[];return `${heading(libraryTitle(type),`${list.length} records · seeded backlog entries are unfinished`,`${btn("add-record","Add record","")}`)}<div class="grid two"><section class="card">${type==="blog"?`<div class="field"><label for="blog-category">Technical category</label><select id="blog-category"><option value="all">All categories</option>${["networking","backend engineering","distributed systems","databases","infrastructure","security","AI","observability"].map(c=>`<option value="${c}" ${categoryFilter===c?"selected":""}>${c}</option>`).join("")}</select></div>`:""}<label class="field"><span>Search records</span><input class="search" id="library-search" value="${esc(libraryFilter)}" placeholder="Filter by title, topic or notes"></label>${filtered.map(x=>`<div class="item"><strong>${esc(x[primary]||"Untitled")}</strong><small>${esc(x.status||"Recorded")}${x.pass?` · Pass ${x.pass}`:""}${x.phase?` · Phase ${x.phase}`:""}</small><div class="row">${link(x.articleUrl||x.paperUrl||x.officialUrl||x.problemUrl||x.githubUrl)}<button class="btn small secondary" data-action="edit-record" data-id="${x.id}">Open / edit</button></div></div>`).join("")||`<p class="sub">No matching records. Add the first one when you begin.</p>`}</section><aside class="grid"><section class="card"><h2>${type==="paper"?"Three-pass reading":type==="lab"?"Experiment workflow":"Work deliberately"}</h2>${type==="paper"?"<p>Pass 1: abstract, introduction, diagrams and conclusion.</p><p>Pass 2: architecture, methodology and solution.</p><p>Pass 3: technical details, experiments and mathematics.</p>":type==="lab"?"<p>Understand → Build → Break → Investigate → Rebuild → Document.</p><p>Predict behavior before creating a controlled failure in your own local test environment.</p>":"<p>Save evidence and the next concrete action. Completion is always explicit.</p>"}</section>${dir.length?`<section class="card"><h2>Source directory</h2>${dir.map(([n,u])=>`<p>${link(u,n)}</p>`).join("")}</section>`:""}</aside></div>`;}
  function renderEditor(){const type=view,record=editing?.id?data.records[type].find(x=>x.id===editing.id):{},fields=schema[type];return `${heading(record?.id?"Edit record":"Add record",libraryTitle(type),`${btn("cancel-edit","Back","quiet")}`)}<form id="record-form" class="card"><div class="form-grid">${fields.map(k=>fieldInput(k,record?.[k]??"")).join("")}</div><div class="row"><button class="btn" type="submit">Save record</button>${record?.id?btn("delete-record","Delete","danger"):""}</div></form>`;}
  function renderTaskEditor(){const {date,id}=editing,r=rec(date,id),extra=id==="deep"?["topic","resource","concepts","exercise","questions"]:[];return `${heading(`Activity notes · ${activity[id]||id}`,date,btn("cancel-edit","Back","quiet"))}<form id="task-form" class="card">${[...extra,"note","next"].map(k=>fieldInput(k,r[k]||"")).join("")}<button class="btn" type="submit">Save notes</button></form>`;}
  function renderVocab(){const terms=data.records.vocab,learned=terms.filter(x=>x.familiarity>0),due=terms.filter(x=>x.nextRevision&&x.nextRevision<=dateKey()),q=libraryFilter.toLowerCase(),filtered=terms.filter(x=>`${x.term} ${x.category} ${x.meaning}`.toLowerCase().includes(q)),term=(due.length?due:terms)[flashIndex%(due.length||terms.length)];return `${heading("Technical vocabulary",`${terms.length} terms available · ${learned.length} learned · ${due.length} due for revision`,`${btn("add-vocab","Quick add term","")}`)}<div class="grid two"><section class="card"><div class="tabs">${btn("flash","Flashcards","quiet")}${btn("explain","Explain it aloud","quiet")}</div>${editing?.mode==="vocab"?`<form id="vocab-form">${["term","category","meaning","definition","example","useCase","tradeoff"].map(k=>fieldInput(k,editing.record?.[k]||"")).join("")}<button class="btn" type="submit">Save term</button>${btn("cancel-edit","Cancel","quiet")}</form>`:editing?.mode==="flash"||editing?.mode==="explain"?`<div class="eyebrow">${editing.mode==="explain"?"Explain without looking":"Revision card"}</div><h2>${esc(term.term)}</h2><p>${esc(term.category)}</p>${showAnswer?`<div class="notice"><b>${esc(term.meaning)}</b><p>${esc(term.example)}</p></div>`:btn("reveal","Reveal definition","secondary")}<div class="field"><label>Self assessment</label><select id="familiarity">${["Unfamiliar","Recognize the term","Understand the concept","Can explain independently","Can apply practically"].map((v,i)=>`<option value="${i}" ${term.familiarity===i?"selected":""}>${v}</option>`).join("")}</select></div>${btn("rate-vocab","Save assessment / next","",showAnswer?"":"disabled")}`:`<p class="sub">Use flashcards to review, or explain a term aloud before revealing its definition.</p>`}</section><section class="card"><label class="field"><span>Search terms</span><input id="library-search" value="${esc(libraryFilter)}" placeholder="Term or category"></label>${filtered.map(x=>`<div class="item"><strong>${esc(x.term)} <span class="badge">${esc(x.category)}</span></strong><small>${x.familiarity?`Level ${x.familiarity}/4 · next review ${esc(x.nextRevision||"unscheduled")}`:"Available, not learned"}</small><details><summary>Definition and example</summary><p>${esc(x.meaning)}</p><p>${esc(x.example)}</p><button class="btn small secondary" data-action="edit-vocab" data-id="${x.id}">Edit</button></details></div>`).join("")}</section></div>`;}
  function renderRoadmap(){const p=phase(dateKey());return `${heading("Six-month roadmap",`Current specialization: ${p.name}`,`${btn("add-phase","Add phase","secondary")}`)}<div class="grid two">${data.roadmap.slice().sort((a,b)=>a.order-b.order).map(x=>{const done=x.topics.filter(t=>t.done).length;return `<section class="card phase"><div class="eyebrow">Phase ${x.order}</div><h2>${esc(x.name)}</h2><p class="sub">${done}/${x.topics.length} topics completed · ${esc(x.tools)}</p><div class="progress"><span style="width:${x.topics.length?done/x.topics.length*100:0}%"></span></div>${x.topics.map(t=>`<div class="item"><label><input type="checkbox" data-topic="${t.id}" data-phase="${x.id}" ${t.done?"checked":""}> ${esc(t.name)}</label></div>`).join("")}<div class="row">${btn("add-topic","Add topic","quiet",`data-id="${x.id}"`)}${btn("move-phase","Move earlier","quiet",`data-id="${x.id}"`)}</div></section>`;}).join("")}</div>`;}
  function renderAnalytics(){const c=challenge(),ss=streaks(),all=Array.from({length:180},(_,i)=>{const key=addDays(data.settings.start,i),s=stats(key),level=key>c.today?0:s.percent===100&&s.total?3:s.percent>=50?2:s.percent>0?1:0;return `<button title="${key}: ${s.percent}%" aria-label="${key}: ${s.percent}% completion" data-action="inspect" data-date="${key}" data-level="${level}" class="${selected===key?"selected":""}"></button>`;}).join("");const full=Object.keys(data.days).filter(k=>{const s=stats(k);return s.total&&s.done===s.total&&data.days[k].mode!=="mvd"}).length,mvd=Object.values(data.days).filter(x=>x.mode==="mvd").length;const counts={dsa:data.records.dsa.length,vocab:data.records.vocab.filter(x=>x.familiarity>0).length,design:data.records.design.filter(x=>x.status==="completed").length,blog:data.records.blog.filter(x=>x.status==="completed").length,paper:data.records.paper.filter(x=>x.status==="completed").length,lab:data.records.lab.filter(x=>x.status==="completed").length,outage:data.records.outage.filter(x=>x.status==="completed").length};const completedTasks=Object.entries(data.days).flatMap(([k,d])=>Object.entries(d.tasks||{}).filter(([,r])=>r.status==="completed").map(([id])=>id));const skipped=Object.entries(data.days).flatMap(([k,d])=>Object.entries(d.tasks||{}).filter(([,r])=>r.status==="skipped").map(([id])=>id));const topSkip=Object.entries(skipped.reduce((m,x)=>(m[x]=(m[x]||0)+1,m),{})).sort((a,b)=>b[1]-a[1])[0];return `${heading("Analytics","Only recorded work counts toward progress")}
  <div class="grid four"><div class="card metric"><b>${ss.current}</b><span>Current streak</span></div><div class="card metric"><b>${ss.longest}</b><span>Longest streak</span></div><div class="card metric"><b>${(Object.values(data.days).reduce((n,d)=>n+Object.values(d.tasks||{}).reduce((a,r)=>a+(Number(r.minutes)||0),0),0)/60).toFixed(1)}</b><span>Focused hours</span></div><div class="card metric"><b>${full} / ${mvd}</b><span>Full / minimum viable days</span></div></div>
  <section class="card" style="margin-top:15px"><h2>Challenge contribution history</h2><p class="sub">Each square is one day. Select one to inspect or correct it.</p><div class="heatmap">${all}</div></section>
  <div class="grid two" style="margin-top:15px"><section class="card"><h2>Weekly consistency trend</h2>${Array.from({length:27},(_,i)=>{const key=addDays(weekStart(data.settings.start),i*7),v=weekStats(key);return `<div class="item"><strong>${key} · ${v.percent}%</strong><div class="progress"><span style="width:${v.percent}%"></span></div></div>`;}).join("")}</section><section class="card"><h2>Monthly phase progress</h2>${data.roadmap.slice().sort((a,b)=>a.order-b.order).map((p,i)=>{const v=spanStats(addDays(data.settings.start,i*30),30),done=p.topics.filter(x=>x.done).length;return `<div class="item"><strong>${esc(p.name)} · ${v.percent}% activity consistency</strong><small>${v.done}/${v.total} required activities · ${done}/${p.topics.length} topics completed</small><div class="progress"><span style="width:${v.percent}%"></span></div></div>`;}).join("")}</section></div>
  <div class="grid two" style="margin-top:15px"><section class="card"><h2>Aspirational targets</h2>${Object.entries(counts).map(([k,n])=>`<div class="item"><strong>${esc(k.toUpperCase())}: ${n} / ${data.settings.targets[k]||0}</strong><div class="progress"><span style="width:${Math.min(100,n/(data.settings.targets[k]||1)*100)}%"></span></div></div>`).join("")}</section><section class="card"><h2>Work quality</h2><p>DSA attempted: ${data.records.dsa.length} · independently solved: ${data.records.dsa.filter(x=>x.solvedIndependently).length}</p><p>Most skipped: ${esc(activity[topSkip?.[0]]||"None recorded")}</p><p>Vocabulary mastery: ${data.records.vocab.filter(x=>x.familiarity>=3).length} can explain or apply.</p><p>Roadmap: ${data.roadmap.flatMap(x=>x.topics).filter(x=>x.done).length} / ${data.roadmap.flatMap(x=>x.topics).length} topics complete.</p><p>Completed activities: ${completedTasks.length}</p><h3>Completion by activity</h3>${Object.entries(activity).map(([id,title])=>`<p>${esc(title)}: ${completedTasks.filter(x=>x===id).length}</p>`).join("")}${data.records.lab.filter(x=>safeLink(x.githubUrl)).map(x=>`<p>${link(x.githubUrl,x.experimentTitle)}</p>`).join("")}</section></div>`;}
  const reviewQuestions=["What did I learn this week that I did not know before?","What did I build independently?","What technical concepts can I now explain confidently?","Where did I struggle?","What distracted me?","Why did I miss certain activities?","What is the most important improvement for next week?","What exact action should I begin with on Monday?"];
  function weeklyRecordCounts(start){const last=addDays(start,6),inWeek=k=>k>=start&&k<=last;return{dsaAttempted:data.records.dsa.filter(x=>inWeek(x.date||x.loggedAt)).length,dsaSolved:data.records.dsa.filter(x=>inWeek(x.date||x.loggedAt)&&x.solvedIndependently).length,vocabLearned:data.records.vocab.filter(x=>inWeek(x.learnedDate)).length,blogs:data.records.blog.filter(x=>inWeek(x.completedAt)).length,design:data.records.design.filter(x=>inWeek(x.completedAt)).length,papers:data.records.paper.filter(x=>inWeek(x.completedAt)||inWeek(x.loggedAt)).length,labs:data.records.lab.filter(x=>inWeek(x.completedAt)).length,outages:data.records.outage.filter(x=>inWeek(x.completedAt)).length,topics:data.roadmap.flatMap(x=>x.topics).filter(x=>inWeek(x.completedAt)).length};}
  function reviewMarkdown(start){const w=weekStats(start),answers=data.reviews[start]?.answers||[];return `# Engineer OS weekly review — ${start}\n\nScheduled: ${w.total}\nCompleted: ${w.done}\nPartially completed: ${w.partial}\nMissed: ${w.total-w.done-w.partial}\nConsistency: ${w.percent}%\nFocused hours: ${(w.focused/60).toFixed(1)}\nDSA attempted: ${data.records.dsa.filter(x=>x.date>=start&&x.date<=addDays(start,6)).length}\nDSA independently solved: ${data.records.dsa.filter(x=>x.date>=start&&x.date<=addDays(start,6)&&x.solvedIndependently).length}\nVocabulary learned: ${data.records.vocab.filter(x=>x.learnedDate>=start&&x.learnedDate<=addDays(start,6)).length}\nBlogs completed: ${weeklyRecordCounts(start).blogs}\nSystem designs completed: ${weeklyRecordCounts(start).design}\nResearch paper progress: ${weeklyRecordCounts(start).papers}\nEngineering experiments completed: ${weeklyRecordCounts(start).labs}\nOutage analyses completed: ${weeklyRecordCounts(start).outages}\nRoadmap topics completed: ${weeklyRecordCounts(start).topics}\n\n${reviewQuestions.map((q,i)=>`## ${q}\n${answers[i]||""}`).join("\n\n")}`;}
  function renderReviews(){const start=weekStart(selected||dateKey()),w=weekStats(start),answers=data.reviews[start]?.answers||[];return `${heading("Weekly reviews",`Week of ${start} · ${w.percent}% required activity consistency`,`${btn("copy-review","Copy Markdown","secondary")}${btn("export-review","Export Markdown","quiet")}`)}<div class="grid two"><form id="review-form" class="card"><h2>Reflection</h2><p class="sub">${w.done} completed · ${w.partial} partial · ${w.total-w.done-w.partial} missed · ${(w.focused/60).toFixed(1)} focused hours</p><div class="notice">DSA ${weeklyRecordCounts(start).dsaAttempted} attempted / ${weeklyRecordCounts(start).dsaSolved} independently solved · ${weeklyRecordCounts(start).vocabLearned} terms learned · ${weeklyRecordCounts(start).blogs} blogs · ${weeklyRecordCounts(start).design} designs · ${weeklyRecordCounts(start).papers} papers progressed · ${weeklyRecordCounts(start).labs} labs · ${weeklyRecordCounts(start).outages} outages · ${weeklyRecordCounts(start).topics} roadmap topics</div>${reviewQuestions.map((q,i)=>`<div class="field"><label for="q${i}">${q}</label><textarea id="q${i}" name="q${i}">${esc(answers[i]||"")}</textarea></div>`).join("")}<button class="btn" type="submit">Save weekly review</button></form><aside class="card"><h2>Previous reviews</h2><input class="search" id="review-search" placeholder="Search saved reviews" value="${esc(libraryFilter)}">${Object.entries(data.reviews).filter(([k,v])=>`${k} ${v.answers.join(" ")}`.toLowerCase().includes(libraryFilter.toLowerCase())).sort((a,b)=>b[0].localeCompare(a[0])).map(([k])=>`<div class="item"><strong>Week of ${k}</strong><button class="btn small secondary" data-action="open-review" data-date="${k}">Open</button></div>`).join("")||`<p class="sub">No saved reviews yet.</p>`}</aside></div>`;}
  function renderSettings(){const s=data.settings;return `${heading("Settings","Challenge configuration and browser-local backup")}<div class="grid two"><form id="settings-form" class="card"><h2>Challenge</h2><div class="form-grid"><div class="field"><label for="start">Start date</label><input id="start" type="date" name="start" value="${esc(s.start)}"></div><div class="field"><label for="weeklyTarget">Weekly target (%)</label><input id="weeklyTarget" type="number" min="1" max="100" name="weeklyTarget" value="${s.weeklyTarget}"></div><div class="field"><label for="timezone">Timezone</label><input id="timezone" name="timezone" value="${esc(s.timezone)}"></div><div class="field"><label for="onboarding">Onboarding</label><select id="onboarding" name="onboarding"><option value="full" ${s.onboarding==="full"?"selected":""}>Complete schedule</option><option value="gradual" ${s.onboarding==="gradual"?"selected":""}>Gradual four-week schedule</option></select></div></div><h3>Time commitments, minutes</h3><div class="form-grid">${Object.entries(s.durations).map(([k,v])=>`<div class="field"><label for="dur-${k}">${activity[k]}</label><input id="dur-${k}" type="number" min="1" max="600" name="dur-${k}" value="${v}"></div>`).join("")}</div><h3>Aspirational targets</h3><div class="form-grid">${Object.entries(s.targets).map(([k,v])=>`<div class="field"><label for="target-${k}">${esc(k.toUpperCase())}</label><input id="target-${k}" type="number" min="1" name="target-${k}" value="${v}"></div>`).join("")}</div><button class="btn" type="submit">Save settings</button></form><aside class="grid"><section class="card"><h2>Backup and restore</h2><p class="sub">All Engineer OS records are stored only in this browser. Prepdesk has its own separate data. Export a JSON backup regularly; browser storage can be cleared by browser settings or device failure.</p>${btn("export-backup","Download JSON backup","")}<div class="field" style="margin-top:18px"><label for="import-file">Restore JSON backup</label><input id="import-file" type="file" accept="application/json,.json"></div><p class="sub">Import validates the schema and asks before replacing current Engineer OS records.</p></section><section class="card"><h2>Schedule</h2><p>Start: ${esc(s.start)} · End: ${end()} · 180 days inclusive.</p><p>Monday–Sunday weekly cycle · ${esc(s.timezone)} calendar dates.</p></section></aside></div>`;}
  const nav=[['today','Today'],['week','Weekly Plan'],['dsa','DSA'],['design','System Design'],['blog','Reading Library'],['vocab','Vocabulary'],['lab','Engineering Labs'],['paper','Research Papers'],['outage','Outage Archive'],['roadmap','Roadmap'],['analytics','Analytics'],['reviews','Weekly Reviews'],['settings','Settings']];
  function render(){const c=challenge();document.body.classList.toggle("hide-focus",focusUi&&view==="focus");const content=editing?.mode==="task"?renderTaskEditor():editing&&schema[view]?renderEditor():({today:renderToday,week:renderWeek,dsa:()=>renderLibrary("dsa"),design:()=>renderLibrary("design"),blog:()=>renderLibrary("blog"),vocab:renderVocab,lab:()=>renderLibrary("lab"),paper:()=>renderLibrary("paper"),outage:()=>renderLibrary("outage"),roadmap:renderRoadmap,analytics:renderAnalytics,reviews:renderReviews,settings:renderSettings,focus:renderFocus}[view]||renderToday)();$("#engineer-app").innerHTML=`<div class="shell"><aside class="side"><a class="brand" href="engineer.html">Engineer OS <small>180-DAY CHALLENGE</small></a><nav aria-label="Engineer OS">${nav.map(([id,title])=>`<button data-view="${id}" class="${view===id?"active":""}">${title}</button>`).join("")}<a href="index.html">Back to Prepdesk</a></nav><footer>Browser-local progress · export backups often</footer></aside><div class="main"><header class="top"><strong>${esc(nav.find(x=>x[0]===view)?.[1]||"Focus")}</strong><span>${c.today} · ${esc(data.settings.timezone)}</span></header><main class="content">${content}</main></div></div>`;}
  function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function begin(key,id){const t=tasks(key).find(x=>x.id===id);if(!t)return;data.focus={date:key,id,running:true,startedAt:Date.now(),remainingMs:t.minutes*60000,note:"",next:rec(key,id).next||"",accumulatedMs:0};day(key).tasks[id]={...rec(key,id),status:"in-progress"};save();view="focus";focusUi=true;render();}
  function pause(){const f=data.focus;if(!f)return;if(f.running){const used=Math.min(f.remainingMs,Date.now()-f.startedAt);f.accumulatedMs+=used;f.remainingMs=Math.max(0,f.remainingMs-used);f.running=false;}else{f.startedAt=Date.now();f.running=true;}save();render();}
  function finish(status){const f=data.focus;if(!f)return;if(f.running){const used=Math.min(f.remainingMs,Date.now()-f.startedAt);f.accumulatedMs+=used;f.remainingMs=Math.max(0,f.remainingMs-used);}const r=rec(f.date,f.id);day(f.date).tasks[f.id]={...r,status:status||r.status,minutes:(Number(r.minutes)||0)+Math.round(f.accumulatedMs/60000),note:f.note||r.note,next:f.next||r.next};data.focus=null;save();focusUi=false;view="today";selected=f.date;render();}
  document.addEventListener("click",async e=>{const n=e.target.closest("[data-view],[data-action]");if(!n)return;if(n.dataset.view){view=n.dataset.view;editing=null;libraryFilter="";categoryFilter="all";selected="";render();return;}const a=n.dataset.action,id=n.dataset.id,key=n.dataset.date||selected||dateKey();try{
    if(a==="start"){const list=tasks(key),mvd=day(key).mode==="mvd",next=list.find(x=>(!mvd||x.id.startsWith("mvd-"))&&!completed(rec(key,x.id)));if(next)begin(key,next.id);else notice="All scheduled activities are complete.";}
    else if(a==="mvd"){day(key).mode=day(key).mode==="mvd"?"normal":"mvd";save();}
    else if(a==="move-up"){const list=tasks(key).map(x=>x.id),index=list.indexOf(id);if(index>0){[list[index-1],list[index]]=[list[index],list[index-1]];day(key).order=list;save();}}
    else if(a==="task-note"){editing={mode:"task",date:key,id};}
    else if(a==="reschedule"){const target=prompt("Reschedule to date (YYYY-MM-DD)",addDays(key,1));if(target&&/^\d{4}-\d{2}-\d{2}$/.test(target)&&target!==key){const t=tasks(key).find(x=>x.id===id);day(target).rescheduled.push({...t,id:`${id}-${key}`,required:false});save();}}
    else if(a==="inspect"){selected=key;view="today";}
    else if(a==="previous-week"||a==="next-week")selected=addDays(weekStart(key),a==="previous-week"?-7:7);
    else if(a==="close-focus"){focusUi=false;view="today";selected=data.focus?.date||key;}
    else if(a==="pause"||a==="resume")pause();
    else if(a==="break"){const f=data.focus;if(f){if(f.running)pause();f.breakUntil=Date.now()+300000;save();notice="Five-minute break started. Resume when ready.";}}
    else if(a==="finish-focus")finish(null);
    else if(a==="complete-focus")finish("completed");
    else if(a==="partial-focus")finish("partial");
    else if(a==="continue-focus"){const f=data.focus;if(f){const date=f.date,id=f.id;finish(null);const all=tasks(date),idx=all.findIndex(x=>x.id===id),next=all.slice(idx+1).find(x=>!completed(rec(date,x.id)));if(next)begin(date,next.id);}}
    else if(a==="add-record"){editing={};}
    else if(a==="edit-record"){editing={id};}
    else if(a==="cancel-edit"){editing=null;}
    else if(a==="delete-record"){if(confirm("Delete this record?")){data.records[view]=data.records[view].filter(x=>x.id!==editing.id);editing=null;save();}}
    else if(a==="add-vocab"){editing={mode:"vocab",record:null};}
    else if(a==="edit-vocab"){editing={mode:"vocab",record:data.records.vocab.find(x=>x.id===id)};}
    else if(a==="flash"||a==="explain"){editing={mode:a};showAnswer=false;}
    else if(a==="reveal")showAnswer=true;
    else if(a==="rate-vocab"){const due=data.records.vocab.filter(x=>x.nextRevision&&x.nextRevision<=dateKey()),t=(due.length?due:data.records.vocab)[flashIndex%(due.length||data.records.vocab.length)],level=Number($("#familiarity").value);t.familiarity=level;t.revisionStatus="reviewed";t.learnedDate=t.learnedDate||(level?dateKey():"");t.nextRevision=addDays(dateKey(),[1,1,3,7,14][level]);flashIndex++;showAnswer=false;save();}
    else if(a==="add-phase"){const name=prompt("New specialization phase name");if(name){data.roadmap.push({id:uid(),name,order:data.roadmap.length+1,tools:"",topics:[]});save();}}
    else if(a==="add-topic"){const name=prompt("New topic");if(name){data.roadmap.find(x=>x.id===id).topics.push({id:uid(),name,done:false});save();}}
    else if(a==="move-phase"){const p=data.roadmap.find(x=>x.id===id),other=data.roadmap.find(x=>x.order===p.order-1);if(other){other.order++;p.order--;save();}}
    else if(a==="open-review"){selected=key;}
    else if(a==="copy-review"){await navigator.clipboard.writeText(reviewMarkdown(weekStart(key)));notice="Weekly review copied as Markdown.";}
    else if(a==="export-review")download(`engineer-review-${weekStart(key)}.md`,reviewMarkdown(weekStart(key)),"text/markdown");
    else if(a==="export-backup")download(`engineer-os-${dateKey()}.json`,JSON.stringify(data,null,2),"application/json");
    render();
  }catch(err){notice=err.message;render();}});
  document.addEventListener("change",async e=>{const t=e.target;if(t.id==="blog-category"){categoryFilter=t.value;render();}else if(t.dataset.complete){const r=rec(t.dataset.date,t.dataset.complete);day(t.dataset.date).tasks[t.dataset.complete]={...r,status:t.checked?"completed":"pending"};save();render();}else if(t.dataset.status){const r=rec(t.dataset.date,t.dataset.status);day(t.dataset.date).tasks[t.dataset.status]={...r,status:t.value};save();render();}else if(t.dataset.topic){const p=data.roadmap.find(x=>x.id===t.dataset.phase),topic=p?.topics.find(x=>x.id===t.dataset.topic);if(topic){topic.done=t.checked;topic.completedAt=t.checked?dateKey():"";save();render();}}else if(t.id==="import-file"){try{const raw=await t.files[0].text(),obj=JSON.parse(raw);if(!valid(obj))throw Error("Unrecognized or incomplete Engineer OS backup");if(!confirm("Replace all existing Engineer OS records in this browser with this backup?"))return;data=obj;save();view="today";selected="";notice="Backup restored.";render();}catch(err){notice=`Import failed: ${err.message}`;render();}}});
  document.addEventListener("input",e=>{const t=e.target;if(t.id==="focus-note"&&data.focus){data.focus.note=t.value;save();}else if(t.id==="focus-next"&&data.focus){data.focus.next=t.value;save();}else if(t.id==="library-search"||t.id==="review-search"){libraryFilter=t.value;const pos=t.selectionStart;render();const again=$("#"+t.id);again?.focus();again?.setSelectionRange(pos,pos);}});
  document.addEventListener("submit",e=>{const f=e.target;if(!["record-form","vocab-form","review-form","settings-form","task-form"].includes(f.id))return;e.preventDefault();const fd=new FormData(f);if(f.id==="task-form"){const {date,id}=editing,r={...rec(date,id)};for(const k of id==="deep"?["topic","resource","concepts","exercise","questions","note","next"]:["note","next"])r[k]=fd.get(k)||"";day(date).tasks[id]=r;editing=null;}else if(f.id==="record-form"){const old=editing?.id?data.records[view].find(x=>x.id===editing.id):null,record={...old,id:old?.id||uid()};for(const k of schema[view])record[k]=["attemptedIndependently","hintRequired","solutionUnderstood","solvedIndependently","revisitRequired"].includes(k)?fd.has(k):fd.get(k)||"";if(view==="dsa")record.date=record.date||dateKey();record.loggedAt=old?.loggedAt||dateKey();if(record.status==="completed"&&old?.status!=="completed")record.completedAt=dateKey();if(record.status&&record.status!=="completed")record.completedAt="";data.records[view]=old?data.records[view].map(x=>x.id===old.id?record:x):[record,...data.records[view]];editing=null;}else if(f.id==="vocab-form"){const old=editing.record,record={...old,id:old?.id||uid()};for(const k of ["term","category","meaning","definition","example","useCase","tradeoff"])record[k]=fd.get(k)||"";record.familiarity??=0;record.revisionStatus??="new";record.nextRevision??="";data.records.vocab=old?data.records.vocab.map(x=>x.id===old.id?record:x):[record,...data.records.vocab];editing=null;}else if(f.id==="review-form"){const start=weekStart(selected||dateKey());data.reviews[start]={answers:reviewQuestions.map((_,i)=>fd.get(`q${i}`)||""),savedAt:new Date().toISOString()};notice="Weekly review saved.";}else if(f.id==="settings-form"){const start=String(fd.get("start"));try{new Intl.DateTimeFormat("en",{timeZone:String(fd.get("timezone"))});}catch{notice="Enter a valid IANA timezone.";render();return;}if(!/^\d{4}-\d{2}-\d{2}$/.test(start)){notice="Enter a valid start date.";render();return;}data.settings.start=start;data.settings.timezone=String(fd.get("timezone"));data.settings.weeklyTarget=Math.min(100,Math.max(1,Number(fd.get("weeklyTarget"))));data.settings.onboarding=String(fd.get("onboarding"));for(const k in data.settings.durations)data.settings.durations[k]=Math.max(1,Number(fd.get(`dur-${k}`))||1);for(const k in data.settings.targets)data.settings.targets[k]=Math.max(1,Number(fd.get(`target-${k}`))||1);notice="Settings saved.";}save();render();});
  try{data=load();view=data.focus?"focus":"today";focusUi=!!data.focus;selected=data.focus?.date||dateKey();render();setInterval(()=>{if(view==="focus"&&data.focus){const f=data.focus,remaining=Math.max(0,Math.ceil((f.remainingMs-(f.running?Date.now()-f.startedAt:0))/1000));const el=$("#focus-clock");if(el)el.textContent=`${String(Math.floor(remaining/60)).padStart(2,"0")}:${String(remaining%60).padStart(2,"0")}`;}const now=dateKey();if(view==="today"&&selected!==now&&selected===addDays(now,-1)){selected=now;render();}},1000);}catch(err){$("#engineer-app").innerHTML=`<main class="content"><h1>Engineer OS could not open</h1><p class="error">${esc(err.message)}</p></main>`;}
})();
